let exportUrl=null,exportBusy=false,exportToken=0;
function closeExport(){exportToken++;document.getElementById('exportOverlay')?.remove();if(exportUrl){URL.revokeObjectURL(exportUrl);exportUrl=null;}exportBusy=false;}
function exportShell(title){closeExport();const box=document.createElement('div');box.id='exportOverlay';box.className='export-overlay';box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-label',title);box.innerHTML=`<div class="export-dialog"><div class="export-toolbar"><h2>${esc(title)}</h2><button class="button" id="exportClose">닫기</button></div><div id="exportContent"></div></div>`;document.body.appendChild(box);$('#exportClose').onclick=closeExport;$('#exportClose').focus();return box;}
function exportError(e){exportBusy=false;console.error('Report export failed',e);const node=document.getElementById('exportStatus');if(node)node.textContent='파일을 만들지 못했습니다. 다시 시도해 주세요. '+(e?.message||'');toast('내보내기에 실패했습니다. 다시 시도해 주세요.');}
function fileLink(blob,name){if(exportUrl)URL.revokeObjectURL(exportUrl);exportUrl=URL.createObjectURL(blob);return `<a class="button primary export-save" id="fileSave" href="${exportUrl}" download="${esc(name)}">↓ ${esc(name)} 저장</a><a class="button" href="${exportUrl}" target="_blank" rel="noopener">파일 새 탭에서 열기</a>`;}
function presentDownload(blob,name,title,auto=false){exportShell(title);$('#exportContent').innerHTML=`<p>파일을 준비했습니다. 아래 저장 버튼으로 다운로드할 수 있습니다.</p><div class="actions">${fileLink(blob,name)}</div><p class="mini">다운로드가 시작되지 않으면 저장 버튼을 직접 클릭하세요. 앱 안에서 저장이 제한되는 경우 <a href="https://plantinet-people.plantynet-9691.chatgpt.site/" target="_blank" rel="noopener">보고 페이지를 새 탭에서 열고</a> 자료를 다시 업로드해 저장할 수 있습니다.</p>`;if(auto)$('#fileSave').click();}
function printableTables(){return reportDatasets().map(([name,rows],i)=>{const columns=rows[0].length;const first=i===0?[]:rows[0],body=i===0?rows:rows.slice(1);return `<section class="pdf-section"><h2>${esc(name)}</h2><table>${first.length?`<thead><tr>${first.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead>`:''}<tbody>${body.map(row=>`<tr>${Array.from({length:columns},(_,j)=>{const v=row[j],percent=['근속별','연령별','직군별','직무별'].includes(name)&&j===2||name==='직급별임금'&&j===6;return `<td>${v==null?'—':typeof v==='number'?percent?fmt(v*100)+'%':fmt(v):esc(v)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></section>`;}).join('');}
function openPrintReport(){if(!state.currentLoaded)return toast('보고 기준일 자료를 먼저 업로드해 주세요.');try{exportShell('인쇄 / PDF 보고서');$('#exportContent').innerHTML=`<div class="actions export-options"><button id="pdfGenerate" class="button primary">↓ PDF 파일 만들기</button><button id="browserPrint" class="button">브라우저 인쇄</button></div><p id="exportStatus" role="status" aria-live="polite">PDF 파일로 저장하거나 브라우저 인쇄를 선택하세요.</p><div id="pdfDownload" class="actions"></div><p class="mini export-options">인쇄창이 열리지 않는 환경에서는 PDF를 저장해 인쇄하세요. 아래 보고서는 두 회사 합산과 선택한 회사의 상세 통계를 포함합니다.</p><article id="printReport"><div class="pdf-heading"><span>PLANTYNET GROUP · CONFIDENTIAL</span><h1>인원현황 보고서</h1><p>${esc(state.company)} · 보고 ${state.date} · 비교 ${state.previousLoaded?state.prevDate:'자료 미등록'}${state.demo?' · 가상 예시자료':''}</p></div>${printableTables()}<p class="pdf-note">개인별 원본자료는 포함하지 않습니다. 연봉은 원 단위 계약연봉이며 실제 지급급여 또는 총 인건비와 다릅니다.</p></article>`;$('#pdfGenerate').onclick=generatePdf;$('#browserPrint').onclick=()=>{try{window.print();$('#exportStatus').textContent='인쇄창이 열리지 않으면 PDF 파일 만들기를 이용하세요.';}catch(e){$('#exportStatus').textContent='이 환경에서 인쇄창을 열 수 없습니다. PDF 파일 만들기를 이용하세요.';}};}catch(e){exportError(e);}}
async function generatePdf(){if(exportBusy)return;const token=exportToken;const button=$('#pdfGenerate');exportBusy=true;button.disabled=true;$('#exportStatus').textContent='PDF 파일을 만드는 중입니다…';let capture=null;try{if(!window.html2canvas||!window.jspdf)throw Error('PDF 구성요소를 불러오지 못했습니다. 페이지를 다시 열어 주세요.');capture=document.createElement('div');capture.className='pdf-capture';const content=$('#printReport').cloneNode(true);content.removeAttribute('id');capture.appendChild(content);document.body.appendChild(capture);if(document.fonts?.ready)await document.fonts.ready;const pdf=new window.jspdf.jsPDF({orientation:'landscape',unit:'mm',format:'a4',compress:true});pdf.setProperties({title:'플랜티넷 그룹 인원현황 보고서',subject:`${state.company} ${state.date}`,creator:'PLANTYNET GROUP'});const blocks=[...content.children];const width=277,bottom=196;let y=12;for(const block of blocks){if(token!==exportToken)return;const canvas=await window.html2canvas(block,{scale:1.8,backgroundColor:'#ffffff',logging:false});if(!canvas.width||!canvas.height)continue;const h=canvas.height*width/canvas.width;if(h<=bottom-12){if(y+h>bottom){pdf.addPage();y=12;}pdf.addImage(canvas.toDataURL('image/png'),'PNG',10,y,width,h);y+=h+5;}else{if(y>12){pdf.addPage();y=12;}const pixelsPerPage=Math.floor((bottom-12)*canvas.width/width);for(let top=0;top<canvas.height;top+=pixelsPerPage){if(top){pdf.addPage();y=12;}const part=document.createElement('canvas');part.width=canvas.width;part.height=Math.min(pixelsPerPage,canvas.height-top);part.getContext('2d').drawImage(canvas,0,top,canvas.width,part.height,0,0,part.width,part.height);const height=part.height*width/part.width;pdf.addImage(part.toDataURL('image/png'),'PNG',10,y,width,height);y+=height+5;}}}if(token!==exportToken)return;const blob=pdf.output('blob'),name=`인원현황_보고_${state.date}.pdf`;$('#pdfDownload').innerHTML=fileLink(blob,name);$('#exportStatus').textContent='PDF 파일을 준비했습니다. 아래 저장 버튼을 클릭하세요.';$('#fileSave').focus();}catch(e){if(token===exportToken)exportError(e);}finally{capture?.remove();if(token===exportToken){exportBusy=false;button.disabled=false;}}}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('exportOverlay'))closeExport();});
